    38→public class OperationSignatureVerifier {
    39→
    40→  private static final Logger LOG = LogManager.getLogger();
    41→
    42→  private final MiscHelpers miscHelpers;
    43→  private final BeaconStateAccessors beaconStateAccessors;
    44→
    45→  public OperationSignatureVerifier(
    46→      final MiscHelpers miscHelpers, final BeaconStateAccessors beaconStateAccessors) {
    47→    this.miscHelpers = miscHelpers;
    48→    this.beaconStateAccessors = beaconStateAccessors;
    49→  }
    50→
    51→  public boolean verifyProposerSlashingSignature(
    52→      final Fork fork,
    53→      final BeaconState state,
    54→      final ProposerSlashing proposerSlashing,
    55→      final BLSSignatureVerifier signatureVerifier) {
    56→
    57→    final BeaconBlockHeader header1 = proposerSlashing.getHeader1().getMessage();
    58→    final BeaconBlockHeader header2 = proposerSlashing.getHeader2().getMessage();
    59→
    60→    Optional<BLSPublicKey> maybePublicKey =
    61→        beaconStateAccessors.getValidatorPubKey(state, header1.getProposerIndex());
    62→    if (maybePublicKey.isEmpty()) {
    63→      return false;
    64→    }
    65→    BLSPublicKey publicKey = maybePublicKey.get();
    66→
    67→    if (!signatureVerifier.verify(
    68→        publicKey,
    69→        miscHelpers.computeSigningRoot(
    70→            header1,
    71→            beaconStateAccessors.getDomain(
    72→                Domain.BEACON_PROPOSER,
    73→                miscHelpers.computeEpochAtSlot(header1.getSlot()),
    74→                fork,
    75→                state.getGenesisValidatorsRoot())),
    76→        proposerSlashing.getHeader1().getSignature())) {
    77→      LOG.trace("Header1 signature is invalid {}", header1);
    78→      return false;
    79→    }
    80→
    81→    if (!signatureVerifier.verify(
    82→        publicKey,
    83→        miscHelpers.computeSigningRoot(
    84→            header2,
    85→            beaconStateAccessors.getDomain(
    86→                Domain.BEACON_PROPOSER,
    87→                miscHelpers.computeEpochAtSlot(header2.getSlot()),
    88→                fork,
    89→                state.getGenesisValidatorsRoot())),
    90→        proposerSlashing.getHeader2().getSignature())) {
    91→      LOG.trace("Header2 signature is invalid {}", header1);
    92→      return false;
    93→    }
    94→    return true;
    95→  }
    96→
    97→  public boolean verifyVoluntaryExitSignature(
    98→      final BeaconState state,
    99→      final SignedVoluntaryExit signedExit,
   100→      final BLSSignatureVerifier signatureVerifier) {
   101→    final VoluntaryExit exit = signedExit.getMessage();
   102→
   103→    final Optional<BLSPublicKey> maybePublicKey =
   104→        beaconStateAccessors.getValidatorPubKey(state, exit.getValidatorIndex());
   105→    if (maybePublicKey.isEmpty()) {
   106→      return false;
   107→    }
   108→
   109→    final Bytes32 domain =
   110→        beaconStateAccessors.getVoluntaryExitDomain(
   111→            exit.getEpoch(), state.getFork(), state.getGenesisValidatorsRoot());
   112→
   113→    final Bytes signingRoot = miscHelpers.computeSigningRoot(exit, domain);
   114→    return signatureVerifier.verify(maybePublicKey.get(), signingRoot, signedExit.getSignature());
   115→  }
   116→
   117→  public boolean verifyBlsToExecutionChangeSignature(
   118→      final BeaconState state,
   119→      final SignedBlsToExecutionChange signedBlsToExecutionChange,
   120→      final BLSSignatureVerifier signatureVerifier) {
   121→    final BlsToExecutionChange addressChange = signedBlsToExecutionChange.getMessage();
   122→    final BLSPublicKey publicKey = addressChange.getFromBlsPubkey();
   123→    final Bytes signingRoot = calculateBlsToExecutionChangeSigningRoot(state, addressChange);
   124→    final BLSSignature signature = signedBlsToExecutionChange.getSignature();
   125→
   126→    return signatureVerifier.verify(publicKey, signingRoot, signature);
   127→  }
   128→
   129→  public SafeFuture<Boolean> verifyBlsToExecutionChangeSignatureAsync(
   130→      final BeaconState state,
   131→      final SignedBlsToExecutionChange signedBlsToExecutionChange,
   132→      final AsyncBLSSignatureVerifier signatureVerifier) {
   133→    final BlsToExecutionChange addressChange = signedBlsToExecutionChange.getMessage();
   134→    final BLSPublicKey publicKey = addressChange.getFromBlsPubkey();
   135→    final Bytes signingRoot = calculateBlsToExecutionChangeSigningRoot(state, addressChange);
   136→    final BLSSignature signature = signedBlsToExecutionChange.getSignature();
   137→
   138→    return signatureVerifier.verify(publicKey, signingRoot, signature);
   139→  }
   140→
   141→  private Bytes calculateBlsToExecutionChangeSigningRoot(
   142→      final BeaconState state, final BlsToExecutionChange addressChange) {
   143→    final Bytes32 domain =
   144→        miscHelpers.computeDomain(
   145→            Domain.DOMAIN_BLS_TO_EXECUTION_CHANGE, state.getGenesisValidatorsRoot());
   146→    return miscHelpers.computeSigningRoot(addressChange, domain);
   147→  }
   148→}
