    34→public class BuilderBidValidatorImpl implements BuilderBidValidator {
    35→
    36→  private static final Logger LOG = LogManager.getLogger();
    37→
    38→  private final Spec spec;
    39→  private final EventLogger eventLogger;
    40→
    41→  public BuilderBidValidatorImpl(final Spec spec, final EventLogger eventLogger) {
    42→    this.spec = spec;
    43→    this.eventLogger = eventLogger;
    44→  }
    45→
    46→  @Override
    47→  public void validateBuilderBid(
    48→      final SignedBuilderBid signedBuilderBid,
    49→      final SignedValidatorRegistration signedValidatorRegistration,
    50→      final BeaconState state,
    51→      final Optional<ExecutionPayload> localExecutionPayload) {
    52→
    53→    // validating Bid Signature
    54→    final Bytes signingRoot =
    55→        spec.computeBuilderApplicationSigningRoot(state.getSlot(), signedBuilderBid.getMessage());
    56→
    57→    if (!BLS.verify(
    58→        signedBuilderBid.getMessage().getPublicKey(),
    59→        signingRoot,
    60→        signedBuilderBid.getSignature())) {
    61→      throw new BuilderBidValidationException("Invalid Bid Signature");
    62→    }
    63→
    64→    final ExecutionPayloadHeader executionPayloadHeader = signedBuilderBid.getMessage().getHeader();
    65→
    66→    // validating payload wrt consensus
    67→    try {
    68→      spec.atSlot(state.getSlot())
    69→          .getBlockProcessor()
    70→          .validateExecutionPayloadHeader(state, executionPayloadHeader);
    71→    } catch (final BlockProcessingException e) {
    72→      throw new BuilderBidValidationException(
    73→          "Invalid proposed payload with respect to consensus.", e);
    74→    }
    75→
    76→    // validating the withdrawals root
    77→    localExecutionPayload
    78→        .flatMap(ExecutionPayload::getOptionalWithdrawalsRoot)
    79→        .ifPresent(
    80→            localWithdrawalsRoot -> {
    81→              final Bytes32 withdrawalsRoot =
    82→                  executionPayloadHeader
    83→                      .getOptionalWithdrawalsRoot()
    84→                      .orElseThrow(
    85→                          () ->
    86→                              new BuilderBidValidationException(
    87→                                  "Proposed payload does not contain withdrawals"));
    88→
    89→              if (!localWithdrawalsRoot.equals(withdrawalsRoot)) {
    90→                final String errorMessage =
    91→                    String.format(
    92→                        "Withdrawals root from the local payload (%s) was different from the proposed payload (%s)",
    93→                        localWithdrawalsRoot, withdrawalsRoot);
    94→                throw new BuilderBidValidationException(errorMessage);
    95→              }
    96→            });
    97→
    98→    final ValidatorRegistration validatorRegistration = signedValidatorRegistration.getMessage();
    99→
   100→    // Show a debug message if the fee recipient in the builder bid differs from the fee recipient
   101→    // specified in the validator registration. This is expected behavior and is not a clear sign of
   102→    // a dishonest builder. They can build a block in advance of knowing who the fee recipient is
   103→    // (giving them more time) using their own fee recipient, then just insert one last transaction
   104→    // into the block to transfer the payment to the requested fee recipient. It probably indicates
   105→    // a smart builder optimizing things well.
   106→    final Eth1Address suggestedFeeRecipient = validatorRegistration.getFeeRecipient();
   107→    if (!executionPayloadHeader.getFeeRecipient().equals(suggestedFeeRecipient)) {
   108→      final Eth1Address payloadHeaderFeeRecipient =
   109→          Eth1Address.fromBytes(executionPayloadHeader.getFeeRecipient().getWrappedBytes());
   110→      LOG.debug(
   111→          "The fee recipient in the builder bid ({}) is not the same as the configured fee recipient ({}) for validator {}."
   112→              + " This is expected behavior. Most likely a builder optimization.",
   113→          payloadHeaderFeeRecipient,
   114→          suggestedFeeRecipient,
   115→          validatorRegistration.getPublicKey());
   116→    }
   117→
   118→    // checking payload gas limit against the validator gas limit preference (if there is an
   119→    // inconsistency, there would be a log warning only instead of an exception)
   120→    final UInt64 parentGasLimit =
   121→        state.toVersionBellatrix().orElseThrow().getLatestExecutionPayloadHeader().getGasLimit();
   122→    final UInt64 preferredGasLimit = validatorRegistration.getGasLimit();
   123→    final UInt64 proposedGasLimit = executionPayloadHeader.getGasLimit();
   124→
   125→    final UInt64 expectedGasLimit = expectedGasLimit(parentGasLimit, preferredGasLimit);
   126→    if (!expectedGasLimit.equals(proposedGasLimit)) {
   127→      eventLogger.builderBidNotHonouringGasLimit(
   128→          parentGasLimit, proposedGasLimit, expectedGasLimit, preferredGasLimit);
   129→    }
   130→  }
   131→
   132→  static UInt64 expectedGasLimit(final UInt64 parentGasLimit, final UInt64 targetGasLimit) {
   133→    final UInt64 maxGasLimitDifference = parentGasLimit.dividedBy(1024L).minusMinZero(1);
   134→    if (targetGasLimit.isGreaterThan(parentGasLimit)) {
   135→      final UInt64 gasDiff = targetGasLimit.minusMinZero(parentGasLimit);
   136→      return parentGasLimit.plus(maxGasLimitDifference.min(gasDiff));
   137→    } else {
   138→      final UInt64 gasDiff = parentGasLimit.minusMinZero(targetGasLimit);
   139→      return parentGasLimit.minusMinZero(maxGasLimitDifference.min(gasDiff));
   140→    }
   141→  }
   142→}
