    38→public class BatchSignatureVerifier implements BLSSignatureVerifier {
    39→
    40→  private static class Job {
    41→    final int idx;
    42→    final List<BLSPublicKey> publicKeys;
    43→    final Bytes message;
    44→    final BLSSignature signature;
    45→
    46→    public Job(
    47→        final int idx,
    48→        final List<BLSPublicKey> publicKeys,
    49→        final Bytes message,
    50→        final BLSSignature signature) {
    51→      this.idx = idx;
    52→      this.publicKeys = publicKeys;
    53→      this.message = message;
    54→      this.signature = signature;
    55→    }
    56→  }
    57→
    58→  @VisibleForTesting final List<Job> toVerify = new ArrayList<>();
    59→  private boolean complete = false;
    60→
    61→  @Override
    62→  public synchronized boolean verify(
    63→      final List<BLSPublicKey> publicKeys, final Bytes message, final BLSSignature signature) {
    64→    if (complete) {
    65→      throw new IllegalStateException("Reuse of disposable instance");
